template <typename T>
struct Pair {
    Pair() = default;
    T first;
    T second;
};

template <typename T>
Pair<T> empty() {
    return Pair<T>{};
}

template <typename T>
Pair<T> zeroed() {
    return Pair<T>();
}

namespace std {
template <typename E>
class initializer_list {
    const E* first;
    decltype(sizeof(0)) count;
};
}  // namespace std

struct Widget {
    Widget(int size);
    Widget(int width, int height);
};

template <typename T>
struct Box {
    Box(T first, T second);
    Box() : Box(T{}, T{}) {}
};

template <typename T>
struct Holder : Box<T> {
    Holder(T value) : Box<T>(value, value) {}
};

template <typename T>
auto pair(T value) {
    return Box(value, value);
}

template <typename T>
using Crate = Box<T>;

template <typename T>
auto crate(T value) {
    return Crate(value, value);
}

template <typename T>
Box<T>* fresh() {
    return new Box<T>;
}

template <typename T>
Widget make(T size) {
    return Widget(size);
}

struct Any {
    template <typename U>
    Any(U value);
};

template <typename T>
Widget braced(T size) {
    return Widget{size, size};
}

template <typename T>
Any wrap(T value) {
    return Any(value);
}

struct Pack {
    template <typename... U>
    Pack(U... values);
};

template <typename T>
Pack gather(T value) {
    return Pack(value, value);
}

struct List {
    List(std::initializer_list<int> values);
};

template <typename T>
List listed(T value) {
    return List{value, value, value};
}

struct Sheet {
    Sheet(int size);
    Sheet(const Sheet& other);
};

struct Page : Sheet {
    using Sheet::Sheet;
};

template <typename T>
Page inherit(T size) {
    return Page(size);
}

template <typename T>
Widget* allocate(T size) {
    return new Widget(size);
}

template <typename... Sizes>
Widget forward(Sizes... sizes) {
    return Widget(sizes...);
}

template <typename T>
struct Wide {
    Wide(T value);
};

template <>
struct Wide<int> {
    Wide(int first, int second = 0);
};

template <typename T>
struct Narrow : Wide<T> {
    Narrow(T value) : Wide<T>(value) {}
};

template <typename T>
T build(int size) {
    return T(size);
}

Holder<int> holder(1);
Narrow<int> narrow(1);
Widget made = make(2);
Widget built = build<Widget>(3);

